<script setup lang="ts">
import type { CorrectionHoldingState, CorrectionPlan } from '~/types/correction'
import { correctionKinds } from '~/utils/correction'
import { displayDecimal } from '~/utils/catalog'
import { formatCreatedAt } from '~/utils/material'
const props = defineProps<{ plan: CorrectionPlan }>()
function observationRow(id: string) { const item = props.plan.observations.find(item => item.reference.id === id); return item?.after ?? item?.before }
const amount = (state: CorrectionHoldingState, unit: string) => state.kind === 'not_established' ? '정산 기준 없음' : `${displayDecimal(state.amounts.quantity)}${unit} · ${state.amounts.value === null ? '가치 미확인' : displayDecimal(state.amounts.value) + '원'}`
</script>
<template>
  <div class="correction-plan">
    <p class="field-hint">원래 기록 위치의 입력을 바꾼 영향입니다. 원기록과 실제 정정 시각은 모두 남으며, 이후 실사에서 실제 확인한 수량은 명시적으로 정정한 행 외에는 유지합니다.</p>
    <section v-for="event in plan.events" :key="event.reference.original_id" class="correction-impact"><h3>{{ correctionKinds[event.reference.kind] }} · 원래 기록 {{ event.reference.logical_seq }}</h3><p class="field-hint">원기록 {{ formatCreatedAt(event.reference.original_recorded_at) }} · 현재 개정 {{ formatCreatedAt(event.reference.recorded_at) }}</p><div class="correction-comparison"><section><h4>정정 전</h4><CorrectionEventValue :value="event.before"/></section><section><h4>정정 후</h4><CorrectionEventValue :value="event.after"/></section></div></section>
    <section v-if="plan.materials.length"><h3>현재 정산 기준에 미치는 영향</h3><ul class="history-list"><li v-for="item in plan.materials" :key="item.material_id"><h4><NuxtLink :to="`/materials/${item.material_id}`">{{ item.material_name }}</NuxtLink></h4><dl><div><dt>정정 전</dt><dd>{{ amount(item.before, item.unit) }}</dd></div><div><dt>정정 후</dt><dd>{{ amount(item.after, item.unit) }}</dd></div><div><dt>변화</dt><dd>{{ displayDecimal(item.quantity_delta) }}{{ item.unit }} · {{ displayDecimal(item.value_delta) }}원</dd></div></dl><p v-if="item.after.kind === 'not_established'" class="field-hint">유효한 시작 근거가 없습니다. 수량 0·가치 0의 확인 기록으로 만들지 않습니다.</p><p v-else-if="item.after.observation_boundary">마지막 유효 실사: <NuxtLink :to="`/stocktakes/${item.after.observation_boundary.stocktake_id}`">{{ displayDecimal(item.after.observation_boundary.quantity) }}{{ item.unit }} · 원래 기록 {{ item.after.observation_boundary.logical_seq }}</NuxtLink></p><p v-if="item.after.kind === 'known' && item.after.last_valid_price" class="field-hint">남은 유효 단가 {{ displayDecimal(item.after.last_valid_price.amount) }}원 / {{ displayDecimal(item.after.last_valid_price.quantity) }}{{ item.unit }} · 근거 {{ item.after.last_valid_price.source.id.slice(0, 8) }}</p></li></ul></section>
    <section v-if="plan.observations.length"><h3>실사 소모·초과·가치 변화</h3><article v-for="item in plan.observations" :key="item.reference.id" class="correction-impact"><NuxtLink :to="`/stocktakes/${item.stocktake_id}`">실사 원기록 {{ item.logical_seq }}</NuxtLink><div class="correction-comparison"><section><h4>정정 전 실사</h4><StocktakeResult v-if="item.before" :rows="[item.before]"/><p v-else>유효한 확인 기록 없음</p></section><section><h4>정정 후 실사</h4><StocktakeResult v-if="item.after" :rows="[item.after]"/><p v-else>이 확인 기록의 유효 효과 취소</p><template v-if="item.valuation_basis"><p class="field-hint">정정 후 가치 근거 {{ displayDecimal(item.valuation_basis.amount) }}원 / {{ displayDecimal(item.valuation_basis.quantity) }}{{ item.after?.unit ?? item.before?.unit ?? '' }} · 근거 기록 {{ item.valuation_basis.logical_seq }} · {{ item.valuation_basis.source.kind === 'proposed' ? '함께 바뀌는 근거' : '보존된 근거' }}</p><p class="material-id">근거 참조 {{ item.valuation_basis.source.id }}</p></template></section></div></article></section>
    <section v-if="plan.allocations.length"><h3>판매 개수에 따른 실사 소모 배분</h3><article v-for="item in plan.allocations" :key="item.observation.id" class="correction-impact"><h4>{{ observationRow(item.observation.id)?.material_name ?? '실사 배분' }}</h4><p class="material-id">실사 근거 {{ item.observation.id }}</p><div class="correction-comparison"><section v-for="side in (['before', 'after'] as const)" :key="side"><h4>{{ side === 'before' ? '정정 전 배분' : '정정 후 배분' }}</h4><template v-if="item[side]"><p>총 소모 {{ displayDecimal(item[side]!.total_quantity) }}{{ observationRow(item.observation.id)?.unit ?? ' (실사 기준 단위)' }} · {{ displayDecimal(item[side]!.total_value) }}원</p><ul class="history-list"><li v-for="candidate in item[side]!.candidates" :key="candidate.sale_id"><NuxtLink :to="`/sales/${candidate.sale_id}`">판매 {{ candidate.sale_id.slice(0, 8) }}</NuxtLink><p>{{ displayDecimal(candidate.count) }}개 · {{ candidate.quantity === null ? '수량 미배분' : displayDecimal(candidate.quantity) + (observationRow(item.observation.id)?.unit ?? ' (실사 기준 단위)') }} · {{ candidate.value === null ? '원가 미배분' : displayDecimal(candidate.value) + '원' }}</p></li></ul><p class="notice">미배분 소모 {{ displayDecimal(item[side]!.unallocated_quantity) }}{{ observationRow(item.observation.id)?.unit ?? ' (실사 기준 단위)' }} · {{ displayDecimal(item[side]!.unallocated_value) }}원<span v-if="item[side]!.reason === 'zero_weight'"> · 총 판매 개수 0</span></p></template><p v-else>유효한 배분 없음</p></section></div></article></section>
    <section v-if="plan.inclusions.length"><h3>실사 포함 연결 변화</h3><article v-for="item in plan.inclusions" :key="item.receipt_id" class="correction-impact"><NuxtLink :to="`/receipts/${item.receipt_id}`">관련 입고 보기</NuxtLink><details v-for="side in (['before', 'after'] as const)" :key="side"><summary>{{ side === 'before' ? '정정 전 포함 근거' : '정정 후 포함 근거' }}</summary><ReceiptReconciliationResult v-if="item[side]" :effect="item[side]!"/><p v-else>유효한 포함 연결 없음</p></details></article></section>
    <section v-if="plan.separate_adjustments.length"><h3>별도 보정 변화</h3><ul class="history-list"><li v-for="item in plan.separate_adjustments" :key="item.receipt_id"><NuxtLink :to="`/receipts/${item.receipt_id}`">입고 {{ item.receipt_id.slice(0, 8) }}</NuxtLink><p>{{ displayDecimal(item.before) }}원 → {{ displayDecimal(item.after) }}원 · 변화 {{ displayDecimal(item.delta) }}원</p></li></ul></section>
    <section v-if="plan.order_closures.length"><h3>주문 입고 연결</h3><ul class="history-list"><li v-for="item in plan.order_closures" :key="item.order_id"><NuxtLink :to="`/orders/${item.order_id}`">주문 보기</NuxtLink><p>이전 {{ item.before ? `입고 ${displayDecimal(item.before.received_quantity)}${item.before.unit}` : '입고 연결 없음' }} → 이후 {{ item.after ? `입고 ${displayDecimal(item.after.received_quantity)}${item.after.unit}` : '입고 연결 해제' }}</p></li></ul></section>
  </div>
</template>
